SET NAMES utf8mb4;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role ENUM('admin','staff','customer') NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NULL, insured_id BIGINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE insureds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, legal_name VARCHAR(180) NOT NULL, dba_name VARCHAR(180) NULL, dot_number VARCHAR(24) NOT NULL UNIQUE, email VARCHAR(254) NULL, phone VARCHAR(50) NULL, address_line1 VARCHAR(180) NULL, address_line2 VARCHAR(180) NULL, city VARCHAR(100) NULL, state VARCHAR(80) NULL, postal_code VARCHAR(20) NULL, country VARCHAR(80) DEFAULT 'USA', status ENUM('active','inactive') DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, vin VARCHAR(50) NOT NULL UNIQUE, unit_number VARCHAR(40) NULL, vehicle_type VARCHAR(80) NULL, make VARCHAR(80) NULL, model VARCHAR(80) NULL, model_year SMALLINT UNSIGNED NULL, value_amount DECIMAL(12,2) NULL, status ENUM('active','inactive') DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_number VARCHAR(100) NOT NULL UNIQUE, carrier_name VARCHAR(180) NULL, insurer_a_name VARCHAR(180) NULL, insurer_a_naic VARCHAR(30) NULL, insurer_b_name VARCHAR(180) NULL, insurer_b_naic VARCHAR(30) NULL, insurer_c_name VARCHAR(180) NULL, insurer_c_naic VARCHAR(30) NULL, insurer_d_name VARCHAR(180) NULL, insurer_d_naic VARCHAR(30) NULL, insurer_e_name VARCHAR(180) NULL, insurer_e_naic VARCHAR(30) NULL, insurer_f_name VARCHAR(180) NULL, insurer_f_naic VARCHAR(30) NULL, business_line VARCHAR(100) NULL, broker_name VARCHAR(180) NULL, finance_company VARCHAR(180) NULL, effective_date DATE NULL, expiration_date DATE NULL, written_premium DECIMAL(13,2) NULL, estimated_fee DECIMAL(13,2) NULL, estimated_tax DECIMAL(13,2) NULL, total_premium DECIMAL(13,2) NULL, status ENUM('draft','active','expired','cancelled') DEFAULT 'draft', certificate_number VARCHAR(100) NULL, revision_number VARCHAR(40) NULL, coverage_data JSON NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE policy_vehicles (policy_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(policy_id,vehicle_id), FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE CASCADE, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE drivers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, full_name VARCHAR(180) NOT NULL, license_number VARCHAR(100) NULL, license_state VARCHAR(80) NULL, date_of_birth DATE NULL, is_excluded TINYINT(1) DEFAULT 0, status ENUM('active','inactive') DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE policy_drivers (policy_id BIGINT UNSIGNED NOT NULL, driver_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(policy_id,driver_id), FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE CASCADE, FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_id BIGINT UNSIGNED NULL, transaction_type VARCHAR(80) DEFAULT 'other', transaction_date DATE NULL, amount DECIMAL(13,2) NULL, reference_number VARCHAR(100) NULL, status VARCHAR(40) DEFAULT 'pending', description TEXT NULL, extra_data JSON NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT, FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE claims (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_id BIGINT UNSIGNED NULL, claim_number VARCHAR(100) NULL, claim_date DATE NULL, incident_date DATE NULL, claim_type VARCHAR(100) NULL, coverage VARCHAR(80) NULL, claim_side VARCHAR(40) NULL, insurance_carrier VARCHAR(180) NULL, adjuster_name VARCHAR(180) NULL, adjuster_contact VARCHAR(180) NULL, status VARCHAR(50) DEFAULT 'New', loss_amount DECIMAL(13,2) NULL, description TEXT NULL, accident_loss_summary TEXT NULL, latest_update_brief TEXT NULL, next_action TEXT NULL, follow_up_date DATE NULL, extra_data JSON NULL, created_by BIGINT UNSIGNED NULL, assigned_team_member_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_claims_follow_up_date (follow_up_date), INDEX idx_claims_coverage (coverage), INDEX idx_claims_claim_side (claim_side), FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT, FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE SET NULL, FOREIGN KEY(assigned_team_member_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, actor_role VARCHAR(30) NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, summary VARCHAR(500) NOT NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE signup_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, email VARCHAR(254) NOT NULL, code_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, attempts TINYINT UNSIGNED DEFAULT 0, verified_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Main-admin-managed producer/contact/signature details used by certificate PDFs.
CREATE TABLE IF NOT EXISTS own_company_settings (
 id TINYINT UNSIGNED NOT NULL PRIMARY KEY DEFAULT 1,
 company_name VARCHAR(180) NOT NULL DEFAULT '',
 company_address TEXT NOT NULL,
 contact_person VARCHAR(180) NOT NULL DEFAULT '',
 phone_number VARCHAR(60) NOT NULL DEFAULT '',
 email_address VARCHAR(254) NOT NULL DEFAULT '',
 authorized_signature_name VARCHAR(180) NOT NULL DEFAULT '',
 authorized_signature_file VARCHAR(80) NULL,
 updated_by BIGINT UNSIGNED NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_own_company_updated_by FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Finance Billing management for admin and staff.
CREATE TABLE IF NOT EXISTS finance_billing (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 insured_id BIGINT UNSIGNED NOT NULL, policy_id BIGINT UNSIGNED NULL,
 status VARCHAR(40) NOT NULL DEFAULT 'Pending Setup',
 coverage_policy_type VARCHAR(80) NOT NULL, finance_company VARCHAR(255) NOT NULL,
 finance_company_other VARCHAR(255) NULL, finance_account_number VARCHAR(100) NULL,
 down_payment DECIMAL(13,2) NULL, installments SMALLINT UNSIGNED NULL,
 monthly_amount DECIMAL(13,2) NULL, next_due_date DATE NULL, pending_past_due DECIMAL(13,2) NULL,
 autopay VARCHAR(20) NULL, payment_method VARCHAR(40) NULL, last_payment_date DATE NULL,
 last_payment_amount DECIMAL(13,2) NULL, billing_notes TEXT NULL,
 created_by BIGINT UNSIGNED NULL, updated_by BIGINT UNSIGNED NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX idx_finance_billing_insured (insured_id), INDEX idx_finance_billing_policy (policy_id), INDEX idx_finance_billing_status (status),
 FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT,
 FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE SET NULL,
 FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,
 FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
